contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function driving c
    function run(address callee, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // do not send ETH to c because C.forward is non-payable; ensure we don't assume msg.value
        // record balances before
        uint balC_before = address(c).balance;
        uint balThis_before = address(this).balance;

        bool reverted;
        // perform the call that may change c; call without value
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balC_after = address(c).balance;
        uint balThis_after = address(this).balance;

        // General rule: either reverted, or succeeded and neither C's balance nor this contract's balance changed
        assert(reverted || (balC_after == balC_before && balThis_after == balThis_before));
    }

    // allow receiving ETH if needed elsewhere
    receive() external payable {}
}

